// generated by nlang -> js
'use strict';

let trackname = document.getElementById("trackname");

let timeinfo = document.getElementById("timeinfo");

let seekbar = document.getElementById("seekbar");

let tl = document.getElementById("tracklist");

let bplay = document.getElementById("bplay");

let bstop = document.getElementById("bstop");

let bprev = document.getElementById("bprev");

let bnext = document.getElementById("bnext");

let vol = document.getElementById("vol");

let seek_hold = false;

let last_tracks = "";

function api(q) {
    fetch(("/api/" + q));
}

function sel(i) {
    api(("select?i=" + i));
}

function mmt(ms) {
    let s = Math.floor((ms / 1000.0));
    let m = Math.floor((s / 60.0));
    let r = (s - (m * 60));
    let ss = ("" + r);
    if ((r < 10)) {
    ss = ("0" + r);
}
    return ((m + ":") + ss);
}

function apply_state(s) {
    trackname.textContent = s.name;
    if ((s.mode === "playing")) {
    bplay.textContent = "❚❚";
} else {
    bplay.textContent = "PLAY";
}
    timeinfo.textContent = ((mmt(s.pos) + " / ") + mmt(s.len));
    if (!(seek_hold && (s.len > 0))) {
    seekbar.value = Math.floor(((s.pos * 1000.0) / s.len));
}
    let sig = ((("" + s.idx) + "|") + s.count);
    if ((sig !== last_tracks)) {
    last_tracks = sig;
    let html = "";
    let i = 0;
    for (const t of s.tracks) {
    let cls = "item";
    if ((i === s.idx)) {
    cls = "item cur";
}
    (html += (((((("<div class=\"" + cls) + "\" onclick=\"sel(") + i) + ")\">") + t) + "</div>"));
    (i += 1);
}
    tl.innerHTML = html;
}
}

function poll() {
    fetch("/api/state").then(function(r) {
    return r.json();
}).then(function(s) {
    apply_state(s);
});
}

function onplay() {
    api("toggle");
}

function onstop() {
    api("stop");
}

function onprev() {
    api("prev");
}

function onnext() {
    api("next");
}

function onseek_down() {
    seek_hold = true;
}

function onseek_up() {
    seek_hold = false;
    api(("seek?pct=" + seekbar.value));
}

function onvol() {
    api(("vol?v=" + vol.value));
}

bplay.addEventListener("click", onplay);

bstop.addEventListener("click", onstop);

bprev.addEventListener("click", onprev);

bnext.addEventListener("click", onnext);

seekbar.addEventListener("mousedown", onseek_down);

seekbar.addEventListener("mouseup", onseek_up);

vol.addEventListener("input", onvol);

setInterval(poll, 400);

poll();

